import (
	"encoding/binary"
	"fmt"
	"io"
	"net"
	"time"
)

func sendFrame(w io.Writer, data string) error {
	payload := []byte(data)
	if err := binary.Write(w, binary.BigEndian, uint32(len(payload))); err != nil {
		return err
	}
	_, err := w.Write(payload)
	return err
}

func readFrame(r io.Reader) (string, error) {
	var length uint32
	if err := binary.Read(r, binary.BigEndian, &length); err != nil {
		return "", err
	}
	buf := make([]byte, length)
	if _, err := io.ReadFull(r, buf); err != nil {
		return "", err
	}
	return string(buf), nil
}

func main() {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	defer l.Close()

	// Сервер принимает кадры
	go func() {
		conn, err := l.Accept()
		if err != nil {
			return
		}
		defer conn.Close()

		for {
			msg, err := readFrame(conn)
			if err != nil {
				return
			}
			fmt.Printf("[Server Frame Received] %s\n", msg)
		}
	}()

	time.Sleep(10 * time.Millisecond)

	// Клиент посылает 3 кадра залпом в одном сокете
	conn, _ := net.Dial("tcp", l.Addr().String())
	defer conn.Close()

	_ = sendFrame(conn, "Кадр #1: Order Created")
	_ = sendFrame(conn, "Кадр #2: Payment Confirmed")
	_ = sendFrame(conn, "Кадр #3: Delivery Shipped")

	time.Sleep(20 * time.Millisecond)
}

package main

import (
	"bufio"
	"fmt"
	"net"
	"sync"
	"time"
)

type ChatServer struct {
	mu      sync.Mutex
	clients map[net.Conn]string
}

func NewChatServer() *ChatServer {
	return &ChatServer{clients: make(map[net.Conn]string)}
}

func (s *ChatServer) Broadcast(sender net.Conn, msg string) {
	s.mu.Lock()
	defer s.mu.Unlock()

	senderName := s.clients[sender]
	formatted := fmt.Sprintf("[%s]: %s\n", senderName, msg)

	for conn := range s.clients {
		if conn != sender {
			_, _ = conn.Write([]byte(formatted))
		}
	}
}

func (s *ChatServer) Handle(conn net.Conn) {
	defer func() {
		s.mu.Lock()
		delete(s.clients, conn)
		s.mu.Unlock()
		conn.Close()
	}()

	reader := bufio.NewReader(conn)
	// Первое сообщение — имя пользователя
	name, err := reader.ReadString('\n')
	if err != nil {
		return
	}

	s.mu.Lock()
	s.clients[conn] = name[:len(name)-1]
	s.mu.Unlock()

	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			return
		}
		s.Broadcast(conn, line[:len(line)-1])
	}
}

func main() {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	defer l.Close()

	chat := NewChatServer()
	go func() {
		for {
			conn, err := l.Accept()
			if err != nil {
				return
			}
			go chat.Handle(conn)
		}
	}()

	time.Sleep(10 * time.Millisecond)

	// Клиент 1 (Alice)
	cAlice, _ := net.Dial("tcp", l.Addr().String())
	defer cAlice.Close()
	_, _ = cAlice.Write([]byte("Alice\n"))

	// Клиент 2 (Bob)
	cBob, _ := net.Dial("tcp", l.Addr().String())
	defer cBob.Close()
	_, _ = cBob.Write([]byte("Bob\n"))

	time.Sleep(10 * time.Millisecond)

	// Alice отправляет сообщение в чат
	_, _ = cAlice.Write([]byte("Привет, Боб! Это TCP сокеты в Go.\n"))

	// Bob слушает входящие сообщения
	bobReader := bufio.NewReader(cBob)
	msg, _ := bobReader.ReadString('\n')
	fmt.Printf("[Экран Боба] Получено сообщение: %s", msg)
}

