package main

import (
	"fmt"
	"net"
)

var privateCIDRs []*net.IPNet

func init() {
	subnets := []string{
		"10.0.0.0/8",     // Class A
		"172.16.0.0/12",  // Class B
		"192.168.0.0/16", // Class C
		"127.0.0.0/8",    // Loopback
		"::1/128",        // IPv6 Loopback
		"fc00::/7",       // IPv6 Private ULA
	}
	for _, cidr := range subnets {
		_, block, _ := net.ParseCIDR(cidr)
		privateCIDRs = append(privateCIDRs, block)
	}
}

func IsPrivateIP(ipStr string) bool {
	ip := net.ParseIP(ipStr)
	if ip == nil {
		return false
	}

	for _, block := range privateCIDRs {
		if block.Contains(ip) {
			return true
		}
	}
	return false
}

func main() {
	testIPs := []string{
		"192.168.1.105",
		"10.244.0.1",
		"172.20.14.5",
		"8.8.8.8",
		"142.250.180.206",
		"::1",
	}

	fmt.Println("Проверка частных (Private) и публичных (Public) IP-адресов:")
	for _, ip := range testIPs {
		isPrivate := IsPrivateIP(ip)
		status := "ПУБЛИЧНЫЙ [PUBLIC]"
		if isPrivate {
			status = "ЧАСТНЫЙ [PRIVATE/RFC1918]"
		}
		fmt.Printf(" -> IP: %-16s | %s\n", ip, status)
	}
}

